    latest_df = df.loc[latest_idx]
    on_book_statuses = ['pending', 'declined', 'failed', 'rejected',
                        'charged off', 'charged_off', 'charged-off', 'charge off',
                        'written off', 'written_off', 'write off',
                        'paid off', 'paid_off', 'fully paid', 'paid in full',
                        'sold', 'closed']
    on_book = latest_df[latest_df['row_kind'] == 'on_book'].copy()

    # NPL definition: dpd >= 90 OR status in non-accrual/default/defaulted
    npl_statuses = {'non-accrual', 'default', 'defaulted'}
    on_book['_is_npl'] = (
        (on_book['Days Past Due'] >= 90) |
        (on_book['Loan Status'].str.lower().isin(npl_statuses))
    )

    products = on_book['Product'].dropna().unique()
    top_products = (
        on_book.groupby('Product')['Loan ID'].count()
        .nlargest(10).index.tolist()
    )

    npl_by_product = []
    for prod in top_products:
        grp = on_book[on_book['Product'] == prod]
        total_bal = grp['Outstanding Principal'].sum()
        npl_bal = grp.loc[grp['_is_npl'], 'Outstanding Principal'].sum()
        ratio = float(npl_bal / total_bal) if total_bal > 0 else float('nan')
        npl_by_product.append({"name": str(prod), "value": round(ratio, 6)})

    result['segments'].append({
        "segment_column": "Product",
        "metric_column": "Outstanding Principal",
        "aggregation": "ratio",
        "label": "npl_ratio",
        "results": npl_by_product
    })

    # Also provide total Outstanding Principal by Product (sum of on_book latest)
    op_by_product = []
    for prod in top_products:
        grp = on_book[on_book['Product'] == prod]
        total_bal = float(grp['Outstanding Principal'].sum())
        op_by_product.append({"name": str(prod), "value": round(total_bal, 2)})

    result['segments'].append({
        "segment_column": "Product",
        "metric_column": "Outstanding Principal",
        "aggregation": "sum",
        "label": None,
        "results": op_by_product
    })

    # Count of on-book loans by product
    count_by_product = []
    for prod in top_products:
        grp = on_book[on_book['Product'] == prod]
        count_by_product.append({"name": str(prod), "value": float(len(grp))})

    result['segments'].append({
        "segment_column": "Product",
        "metric_column": "Loan ID",
        "aggregation": "count",
        "label": None,
        "results": count_by_product
    })

    # Overall NPL ratio (pooled)
    total_bal_all = on_book['Outstanding Principal'].sum()
    npl_bal_all = on_book.loc[on_book['_is_npl'], 'Outstanding Principal'].sum()
    overall_npl = float(npl_bal_all / total_bal_all) if total_bal_all > 0 else float('nan')

    result['segments'].append({
        "segment_column": "Product",
        "metric_column": "Outstanding Principal",
        "aggregation": "ratio",
        "label": "npl_ratio_overall",
        "results": [{"name": "All Products", "value": round(overall_npl, 6)}]
    })

    result['assumptions'].append(
        "NPL = dpd >= 90 or Loan Status in {non-accrual, default, defaulted}; "
        "balance uses each Loan ID's latest on_book snapshot only."
    )
    result['assumptions'].append(
        "Charged-off, paid-off, closed and other non-on_book rows excluded from denominator and numerator."
