    # Delinquency 30+: balance where DPD >= 30
    delinq_mask = on_book_latest['Days Past Due'] >= 30

    # Per product: delinquency ratio = sum(balance where dpd>=30) / sum(balance)
    products = on_book_latest.groupby('Product')

    delinq_results = []
    for prod, grp in products:
        prod_total = grp['Outstanding Principal'].sum()
        prod_delinq = grp.loc[grp['Days Past Due'] >= 30, 'Outstanding Principal'].sum()
        ratio = float(prod_delinq / prod_total) if prod_total > 0 else 0.0
        delinq_results.append({"name": str(prod), "value": round(ratio, 6)})

    delinq_results_sorted = sorted(delinq_results, key=lambda x: x['value'], reverse=True)

    # Overall delinquency ratio
    overall_delinq_balance = on_book_latest.loc[delinq_mask, 'Outstanding Principal'].sum()
