    abs_results = []
    for prod, grp in products:
        prod_delinq_bal = grp.loc[grp['Days Past Due'] >= 30, 'Outstanding Principal'].sum()
        abs_results.append({"name": str(prod), "value": round(float(prod_delinq_bal), 2)})

    abs_results_sorted = sorted(abs_results, key=lambda x: x['value'], reverse=True)

    result['segments'].append({
        "segment_column": "Product",
        "metric_column": "Outstanding Principal",
        "aggregation": "sum",
        "label": "delinquent_balance_30plus",
        "results": abs_results_sorted
    })

