        "Latest snapshot per Loan ID taken across all row kinds; then filtered to on_book only before computing balances."
    )
    result['assumptions'].append(
        f"Overall 30+ delinquency ratio across all products: {overall_ratio:.4f} (delinquent balance / total on-book balance)."
    )
    result['assumptions'].append(
        "Delinquency_30 ratio = sum(Outstanding Principal where Days Past Due >= 30) / sum(Outstanding Principal), per product."
    )

